class LRUCache {
  constructor(capacity, now = Date.now) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error('Capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.now = now;
    this.cache = new Map();
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
